-- =============================================================================
-- Migration: starter characters (Arjun, Meera), free face items and outfits
-- Builds on 20261011120000_avatar_shop_clothing_slots.sql. Safe to run more than once.
--
-- Arjun (avatars/ojas_default.glb) and Meera (avatars/ojas_female.glb) are Rocketbox
-- (MIT) bodies in matching plain zip jackets, joggers and shoes, each its own material, so the shop's
-- top / pants / shoes colour items fit them. Arjun is the new default; Aiko is retired.
-- New category 'face': a head GLB on the character's skeleton that hides its own head
--   { "model_url", "hide": ["ojas_head", "ojas_neck"], "tint": { "<material>": [r, g, b] } }
-- (tint brings the body's skin to the face's tone). Faces are free, one character each.
-- New category 'kit': a whole outfit, another Rocketbox character's clothes fitted to the
-- starter's skeleton; it hides the starter's own clothes and neck. Sold for coins.
-- The face and outfit rows are generated by model/instructor/ojas/gen_catalog.py.
-- =============================================================================

-- 1. Categories and unequip
ALTER TABLE public.avatar_models DROP CONSTRAINT IF EXISTS avatar_models_category_check;
ALTER TABLE public.avatar_models
  ADD CONSTRAINT avatar_models_category_check
  CHECK (category IN ('character', 'face', 'kit', 'top', 'pants', 'shoes', 'hair', 'accessory'));

CREATE OR REPLACE FUNCTION public.unequip_avatar_slot(p_slot TEXT)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_uid UUID := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Sign in to change your avatar.');
  END IF;
  IF p_slot NOT IN ('face', 'kit', 'top', 'pants', 'shoes', 'hair', 'accessory') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Unknown slot.');
  END IF;

  UPDATE public.profiles
  SET equipped_items = jsonb_set(
        COALESCE(equipped_items, '{}'::jsonb),
        ARRAY[equipped_avatar_id],
        COALESCE(equipped_items -> equipped_avatar_id, '{}'::jsonb) - p_slot
      ),
      updated_at = NOW()
  WHERE id = v_uid;

  RETURN jsonb_build_object('ok', true);
END;
$$;

REVOKE ALL ON FUNCTION public.unequip_avatar_slot(TEXT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.unequip_avatar_slot(TEXT) TO authenticated;

-- 2. The starters
