   'local://avatars/ojas_default.glb', 'glb',
   '{"materials": {"top": ["ojas_top"], "pants": ["ojas_pants"], "shoes": ["ojas_shoes"]}}', 'local://avatars/ojas_default.png', TRUE, 0),
  ('starter_ojas_f', 'Meera', 'Every athlete starts here. Pick a face and earn coins for new gear.', 'common', 0, 'character', NULL,
   'local://avatars/ojas_female.glb', 'glb',
