  ('kit_f_fire', 'Firefighter', 'Full turnout gear.', 'legendary', 1100, 'kit', 'starter_ojas_f', '', 'glb', '{"model_url": "local://avatars/outfits/f_fire.glb", "hide": ["ojas_skin", "ojas_top", "ojas_pants", "ojas_shoes", "ojas_neck"]}', 'local://avatars/outfits/f_fire.png', 120)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, rarity = EXCLUDED.rarity,
  price_coins = EXCLUDED.price_coins, character_id = EXCLUDED.character_id, config = EXCLUDED.config,
  thumbnail_url = EXCLUDED.thumbnail_url, sort_order = EXCLUDED.sort_order, is_active = TRUE;

-- 4. New profiles own both starters and play as Arjun
ALTER TABLE public.profiles
  ALTER COLUMN owned_avatar_ids SET DEFAULT ARRAY['starter_ojas', 'starter_ojas_f']::TEXT[],
  ALTER COLUMN equipped_avatar_id SET DEFAULT 'starter_ojas';

CREATE OR REPLACE FUNCTION public.protect_profile_avatar_columns()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = public
AS $$
BEGIN
  IF current_user IN ('authenticated', 'anon') THEN
    IF TG_OP = 'INSERT' THEN
      NEW.owned_avatar_ids := ARRAY['starter_ojas', 'starter_ojas_f']::TEXT[];
      NEW.equipped_avatar_id := 'starter_ojas';
      NEW.equipped_items := '{}'::jsonb;
      NEW.coins_spent := 0;
    ELSE
      NEW.owned_avatar_ids := OLD.owned_avatar_ids;
      NEW.equipped_avatar_id := OLD.equipped_avatar_id;
      NEW.equipped_items := OLD.equipped_items;
      NEW.coins_spent := OLD.coins_spent;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

-- 5. Existing players own the new starters; everyone playing as Aiko switches to Arjun
UPDATE public.profiles
SET owned_avatar_ids = ARRAY(SELECT DISTINCT unnest(owned_avatar_ids || ARRAY['starter_ojas', 'starter_ojas_f']::TEXT[]))
WHERE NOT (owned_avatar_ids @> ARRAY['starter_ojas', 'starter_ojas_f']::TEXT[]);

UPDATE public.profiles
SET equipped_avatar_id = CASE WHEN equipped_avatar_id = 'starter_aiko' THEN 'starter_ojas' ELSE equipped_avatar_id END,
    owned_avatar_ids = array_remove(owned_avatar_ids, 'starter_aiko'),
    equipped_items = COALESCE(equipped_items, '{}'::jsonb) - 'starter_aiko'
WHERE equipped_avatar_id = 'starter_aiko' OR 'starter_aiko' = ANY(owned_avatar_ids) OR equipped_items ? 'starter_aiko';
